window.products.push({"id":1143654,"name":"Chef'n Pocket Machine Mini Pocket Maker","category":"homeandappliances","retail price":9.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61Qv+GREbVL._AC_SL1440_.jpg","description":"Breeze through food preparation tasks with the beautifully designed Chef'n Pocket Machine Mini Pocket Maker. Create homemade turnovers, pot stickers, and more with this kitchen gadget. Place circles of dough on the machine and twist the top to create a pocket for filling with ingredients. Clamp the sides together for perfectly sealed and scalloped edges. Bake or fry the assembled creation for bite-sized snacks with friends and family on any occasion. Get started quickly with the included recipe book.","images":["https://m.media-amazon.com/images/I/61Qv+GREbVL._AC_SL1440_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Chef'n","source_asin":"B00DVGLKEK","category_path":"Home & Kitchen"},"sku":"BM-1143654","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00DVGLKEK","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00DVGLKEK","price_pending":true,"merchant_ready":false});
